selected.compute:
options = read('/input/options')
ids = []
for r in options:
    ids = ids + [r['id']]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for c in combinations(ids, k):
        if valid(list(c)):
            result = list(c)
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if not valid(selection):
        status('report')
    else:
        if receipt('report') == 'success':
            if exists('/tmp/cache'):
                delete('/tmp/cache')
        else:
            if receipt('report') == 'unknown':
                status('report')
            if receipt('report') == 'unattempted' or status('report') == 'not_sent':
                send('report', 'team', selection)
            if exists('/tmp/cache'):
                delete('/tmp/cache')
else:
    if result and valid(result):
        write('/output/selection', result)
        send('report', 'team', result)
        if exists('/tmp/cache'):
            delete('/tmp/cache')
